  "I was relieved that he’d fully recovered from my electric spell.",
  "If he hadn’t regained consciousness, I wouldn’t know what to tell Ginger.",
  "",
  "Cliff, on the other hand, had changed.",
  "Immediately after the battle, he’d spoken with Kishirika and I’d wondered what that was about.",
  "It turned out they were discussing his reward for helping her before—a demon eye.",
  "He got the Eye of Identification from her.",
  "It allowed him to look at any item and understand its characteristics.",
  "He chose it so that he would be able to help if anything like Nanahoshi’s illness ever happened again.",
  "As always, Cliff was nothing if not heroic.",
  "",
  "That heroism, however, wasn’t helping him to master the eye.",
